import type { CustomDesign } from './types'

type Idea = readonly [name: string, description: string, tags: readonly string[]]
type Built = { html: string; css: string; js?: string }

const esc = (value: string) => value.replace(/[<>]/g, '')
const slug = (value: string) => value.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')

const seed = (number: number, category: string, idea: Idea, built: Built): CustomDesign => ({
  id: `extreme-${String(number).padStart(3, '0')}-${slug(idea[0])}`,
  name: idea[0],
  category,
  description: idea[1],
  html: built.html,
  css: built.css,
  js: built.js,
  tags: [...idea[2], 'extreme-100'],
  source: 'seed',
})

