function buildButton(index: number, idea: Idea): Built {
  const isBurst = index === 4
  const html = isBurst
    ? `<span class="x100-wrap"><button class="x100-btn" type="button"><span>${esc(idea[0].replace(' Button', ''))}</span></button></span>`
    : `<button class="x100-btn" type="button"><span>${esc(idea[0].replace(' Button', ''))}</span><i></i><b></b></button>`
  let js: string | undefined
  if (index === 2) js = `const b=document.querySelector('.x100-btn');b.addEventListener('pointermove',e=>{const r=b.getBoundingClientRect(),x=e.clientX-r.left-r.width/2,y=e.clientY-r.top-r.height/2;b.style.setProperty('--mx',(x*.16)+'px');b.style.setProperty('--my',(y*.16)+'px');b.style.setProperty('--px',((e.clientX-r.left)/r.width*100)+'%');b.style.setProperty('--py',((e.clientY-r.top)/r.height*100)+'%')});b.addEventListener('pointerleave',()=>{b.style.setProperty('--mx','0px');b.style.setProperty('--my','0px')})`
  if (index === 4) js = `const w=document.querySelector('.x100-wrap'),b=document.querySelector('.x100-btn');b.addEventListener('click',()=>{for(let i=0;i<16;i++){const p=document.createElement('i'),a=Math.PI*2*i/16,d=45+Math.random()*55;p.className='x100-particle';p.style.setProperty('--x',Math.cos(a)*d+'px');p.style.setProperty('--y',Math.sin(a)*d+'px');p.style.setProperty('--h',String((i*27)%360));w.appendChild(p);setTimeout(()=>p.remove(),700)}})`
  if (index === 6) js = `const b=document.querySelector('.x100-btn');b.addEventListener('pointermove',e=>{const r=b.getBoundingClientRect();b.style.setProperty('--px',((e.clientX-r.left)/r.width*100)+'%')})`
  return { html, css: buttonVariants[index], js }
}

