function loginBase(extra = '') {
  return `.x100-login{position:relative;width:250px;padding:20px;border:1px solid #ffffff18;border-radius:20px;background:#10131a;color:#fff;transform-style:preserve-3d}.x100-login h3{margin:0 0 3px;font:800 18px Inter,sans-serif;letter-spacing:-.04em}.x100-login small{display:block;margin-bottom:14px;color:#788191;font:500 10px Inter,sans-serif}.x100-login input{display:block;width:100%;height:37px;margin:7px 0;border:1px solid #ffffff12;border-radius:10px;background:#171a22;color:#fff;padding:0 10px;outline:none}.x100-login button{width:100%;height:38px;margin-top:7px;border:0;border-radius:10px;background:#756cff;color:#fff;font-weight:800;cursor:pointer}.x100-face{display:none}${extra}`
}

function buildLogin(index: number, idea: Idea): Built {
  const face = index === 3 ? `<span class="x100-face"></span>` : ''
  const vault = index === 9 ? `<span class="x100-vault"></span>` : ''
  const html = `<form class="x100-login">${vault}${face}<h3>${esc(idea[0].replace(' Login', ''))}</h3><small>Welcome back to RED UI</small><input aria-label="Email" placeholder="email@red.ui"><input class="x100-password" aria-label="Password" type="password" placeholder="••••••••"><button type="button">Continue</button></form>`
  let js: string | undefined
  if (index === 0) js = `const c=document.querySelector('.x100-login');c.addEventListener('pointermove',e=>{const r=c.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;c.style.setProperty('--ry',(x*12)+'deg');c.style.setProperty('--rx',(-y*10)+'deg')});c.addEventListener('pointerleave',()=>{c.style.setProperty('--rx','0deg');c.style.setProperty('--ry','0deg')})`
  if (index === 2 || index === 9) js = `const c=document.querySelector('.x100-login'),b=c.querySelector('button');b.addEventListener('click',()=>{c.classList.remove('success');void c.offsetWidth;c.classList.add('success');setTimeout(()=>c.classList.remove('success'),1500)})`
  if (index === 3) js = `const c=document.querySelector('.x100-login'),p=c.querySelector('.x100-password');p.addEventListener('focus',()=>c.classList.add('looking-away'));p.addEventListener('blur',()=>c.classList.remove('looking-away'))`
  return { html, css: loginBase(loginVariantCss[index]), js }
}

