function buildDashboard(index: number, idea: Idea): Built {
  const html = `<div class="x100-dash"><header><b>${esc(idea[0].replace(' Dashboard', ''))}</b><i>● LIVE</i></header><div class="x100-kpis"><article class="x100-kpi"><small>Energy</small><strong>84%</strong></article><article class="x100-kpi"><small>Focus</small><strong>7.2h</strong></article><article class="x100-kpi"><small>Flow</small><strong>+28</strong></article></div><div class="x100-chart"><span class="x100-bar" style="height:48%"></span><span class="x100-bar" style="height:78%"></span><span class="x100-bar" style="height:61%"></span><span class="x100-bar" style="height:88%"></span></div></div>`
  const base = `.x100-dash{position:relative;width:300px;padding:15px;border:1px solid #ffffff13;border-radius:19px;background:#10131a;color:#fff;overflow:visible;transform-style:preserve-3d}.x100-dash header{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px;font:800 12px Inter,sans-serif}.x100-dash header i{font-style:normal;color:#2dd4bf;font-size:8px;letter-spacing:.08em}.x100-kpis{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.x100-kpi{padding:10px;border:1px solid #ffffff0f;border-radius:12px;background:#171a22;transition:.3s}.x100-kpi small{display:block;color:#78808e;font:600 8px Inter,sans-serif}.x100-kpi strong{display:block;margin-top:4px;font:900 15px Inter,sans-serif}.x100-chart{height:82px;margin-top:10px;padding:10px;border-radius:12px;background:#0b0d12;display:flex;align-items:end;gap:8px}.x100-bar{display:block;flex:1;border-radius:5px 5px 2px 2px;background:linear-gradient(#756cff,#4438b8)}`
  let js: string | undefined
  if ([2, 6, 8].includes(index)) js = `const d=document.querySelector('.x100-dash');d.addEventListener('pointermove',e=>{const r=d.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;d.style.setProperty('--px',(x/r.width*100)+'%');d.style.setProperty('--py',(y/r.height*100)+'%');d.style.setProperty('--dx',(x-r.width/2)*.12+'px');d.style.setProperty('--dy',(y-r.height/2)*.12+'px')});d.addEventListener('pointerleave',()=>{d.style.setProperty('--dx','0px');d.style.setProperty('--dy','0px')})`
  return { html, css: base + dashboardVariants[index], js }
}

