function buildToggle(index: number, idea: Idea): Built {
  const html = `<label class="x100-toggle"><input type="checkbox"><span class="x100-track"><i class="x100-knob"></i><b class="x100-deco"></b><em></em></span></label>`
  const base = `.x100-toggle{position:relative;display:inline-block;width:92px;height:46px;cursor:pointer}.x100-toggle input{position:absolute;opacity:0}.x100-track{position:absolute;inset:0;border:1px solid #ffffff18;border-radius:999px;background:#1b1e25;box-shadow:inset 0 5px 12px #0007,0 12px 25px #0005;overflow:hidden;transition:.5s}.x100-knob{position:absolute;width:34px;height:34px;left:6px;top:5px;border-radius:50%;background:linear-gradient(#fff,#cbd0da);box-shadow:0 6px 12px #0007;transition:.55s cubic-bezier(.2,.9,.2,1.2);z-index:3}.x100-toggle input:checked+.x100-track .x100-knob{transform:translateX(46px)}.x100-deco,.x100-track em{position:absolute;pointer-events:none}`
  const variants = [
    `.x100-track{border-radius:15px;background:linear-gradient(#343842,#171920);box-shadow:inset 0 5px 0 #0c0d11,0 8px 0 #090a0d,0 16px 25px #0006}.x100-knob{border-radius:11px;background:linear-gradient(#89909b,#3e434d);box-shadow:inset 0 2px #fff4,0 5px 0 #17191e}.x100-toggle input:checked+.x100-track{background:linear-gradient(#276d62,#103a34)}.x100-toggle input:checked+.x100-track .x100-knob{background:linear-gradient(#67e8d4,#2bb6a0)}`,
    `.x100-track:before{content:"";position:absolute;left:-45px;top:-18px;width:105px;height:82px;border-radius:48% 52% 60% 40%;background:linear-gradient(145deg,#22d3ee,#756cff);transition:transform .7s cubic-bezier(.2,.8,.2,1);filter:blur(2px)}.x100-toggle input:checked+.x100-track:before{transform:translateX(78px) rotate(160deg)}.x100-knob{background:#ffffffdd;backdrop-filter:blur(7px)}`,
    `.x100-track{background:linear-gradient(#88c9ff,#dff4ff)}.x100-knob{background:radial-gradient(circle at 35% 35%,#fff,#ffd45a 28%,#ff9e38 70%);box-shadow:0 0 18px #ffd45a}.x100-toggle input:checked+.x100-track{background:linear-gradient(#101632,#29244c)}.x100-toggle input:checked+.x100-track .x100-knob{background:radial-gradient(circle at 35% 35%,#fff,#dbe8ff 30%,#8b9bb8 72%);box-shadow:0 0 15px #c8dcff}.x100-track:after{content:"✦ ·";position:absolute;right:12px;top:10px;color:white;opacity:0;transition:.4s}.x100-toggle input:checked+.x100-track:after{opacity:.8}`,
    `.x100-track{background:linear-gradient(#233b56,#152435)}.x100-deco:before{content:"☁";position:absolute;left:13px;top:7px;color:#b9d5ed;font-size:24px;transition:.5s}.x100-deco:after{content:"⋮ ⋮";position:absolute;left:17px;top:23px;color:#7dd3fc;letter-spacing:4px;font-size:12px;transition:.5s}.x100-toggle input:checked+.x100-track{background:linear-gradient(#74c8ff,#c4efff)}.x100-toggle input:checked+.x100-track .x100-deco:before{content:"☀";left:55px;color:#ffd44e;transform:rotate(180deg)}.x100-toggle input:checked+.x100-track .x100-deco:after{opacity:0}`,
    `.x100-track{background:#080c10;border-color:#22d3ee55}.x100-track:before{content:"";position:absolute;left:11px;right:11px;top:21px;height:2px;background:#16414a;box-shadow:0 0 5px #22d3ee}.x100-track:after{content:"";position:absolute;left:10px;top:19px;width:10px;height:6px;background:#fff;clip-path:polygon(0 40%,42% 40%,55% 0,100% 50%,58% 50%,46% 100%);opacity:0}.x100-toggle input:checked+.x100-track:after{opacity:1;animation:x100-electric 1s linear infinite}.x100-toggle input:checked+.x100-track{box-shadow:inset 0 0 18px #22d3ee22,0 0 24px #22d3ee33}@keyframes x100-electric{to{transform:translateX(58px)}}`,
    `.x100-track:before,.x100-track:after{content:"";position:absolute;top:8px;width:30px;height:30px;border-radius:50%;border:1px solid #756cff88;box-shadow:inset 0 0 14px #756cff66,0 0 14px #756cff33}.x100-track:before{left:7px}.x100-track:after{right:7px}.x100-knob{background:radial-gradient(circle,#fff,#bcb6ff 28%,#4c3fc5 65%)}.x100-toggle input:checked+.x100-track .x100-knob{animation:x100-portal-knob .55s ease both}@keyframes x100-portal-knob{40%{transform:translateX(20px) scale(.05)}60%{transform:translateX(28px) scale(.05)}100%{transform:translateX(46px) scale(1)}}`,
    `.x100-track{background:radial-gradient(circle at 20px 23px,#ffdb65 0 7px,#ff9c2f 8px 9px,transparent 10px),#10162a}.x100-knob{width:24px;height:24px;top:10px;left:11px;background:radial-gradient(circle at 35% 30%,#d9f2ff,#5994c7 55%,#244361);box-shadow:0 0 0 6px #ffffff0b,0 0 18px #60a5fa;transform-origin:35px 12px}.x100-toggle input:checked+.x100-track .x100-knob{transform:translateX(46px) rotate(360deg)}`,
    `.x100-knob{background:none;box-shadow:none;font-style:normal}.x100-knob:before{content:"🚀";position:absolute;inset:2px;display:grid;place-items:center;font-style:normal;font-size:25px;transform:rotate(45deg);transition:.55s}.x100-track:after{content:"";position:absolute;left:18px;top:31px;width:10px;height:3px;background:#22d3ee;box-shadow:0 0 10px #22d3ee;opacity:.25}.x100-toggle input:checked+.x100-track .x100-knob:before{transform:rotate(45deg) scale(1.15)}.x100-toggle input:checked+.x100-track:after{left:64px;opacity:1}`,
    `.x100-knob{background:none;box-shadow:none}.x100-knob:before{content:"♟";position:absolute;inset:0;display:grid;place-items:center;font-size:27px;color:#f2f4f7;transition:.4s}.x100-toggle input:checked+.x100-track .x100-knob:before{animation:x100-walk .55s steps(4)}@keyframes x100-walk{25%{transform:rotate(-12deg) translateY(-2px)}50%{transform:rotate(12deg)}75%{transform:rotate(-8deg) translateY(-2px)}}`,
    `.x100-knob{left:29px;background:#756cff;color:white;box-shadow:0 0 20px #756cff66}.x100-knob:before,.x100-knob:after{content:"";position:absolute;left:9px;right:9px;top:16px;height:2px;background:#fff;border-radius:2px;transition:.45s}.x100-knob:after{transform:rotate(90deg)}.x100-toggle input:checked+.x100-track .x100-knob{transform:none;background:#2dd4bf;box-shadow:0 0 20px #2dd4bf66}.x100-toggle input:checked+.x100-track .x100-knob:before{transform:translate(-2px,1px) rotate(42deg);width:12px}.x100-toggle input:checked+.x100-track .x100-knob:after{transform:translate(4px,-2px) rotate(-48deg);width:18px}`,
  ]
  return { html, css: base + variants[index] }
}

