function buildSearch(index: number, idea: Idea): Built {
  const html = `<div class="x100-search"><div class="x100-search-row"><i>⌕</i><input value="RED" aria-label="Search"><button type="button">×</button><span class="x100-ai-orb"></span><span class="x100-wave"><b></b><b></b><b></b><b></b></span></div><div class="x100-results"><span>Design systems</span><span>RED motion</span><span>3D components</span></div><em class="x100-magnifier">⌕</em></div>`
  const base = `.x100-search{position:relative;width:280px;color:#fff;perspective:700px}.x100-search-row{position:relative;height:48px;border:1px solid #ffffff18;border-radius:15px;background:#11141b;display:flex;align-items:center;padding:0 11px;gap:8px;box-shadow:0 16px 32px #0006;z-index:4;transition:.4s}.x100-search-row>i{font-style:normal;color:#7d8594;font-size:22px}.x100-search input{min-width:0;flex:1;border:0;outline:0;background:transparent;color:#fff;font:600 12px Inter,sans-serif}.x100-search-row>button{border:0;background:transparent;color:#6f7785;cursor:pointer}.x100-results{margin:7px 8px 0;padding:9px;border:1px solid #ffffff0f;border-radius:12px;background:#0d0f15;display:grid;gap:6px;transition:.4s}.x100-results span{padding:7px 8px;border-radius:8px;background:#ffffff05;color:#9ca3af;font:600 9px Inter,sans-serif}.x100-ai-orb,.x100-wave,.x100-magnifier{display:none}`
  const variants = [
    `.x100-search-row{border-radius:24px 16px 24px 17px;width:185px;transition:width .55s cubic-bezier(.2,.9,.2,1.1),border-radius .55s}.x100-search-row:focus-within{width:280px;border-radius:16px 24px 17px 23px;box-shadow:0 0 24px #756cff22,0 18px 32px #0006}.x100-search-row:before{content:"";position:absolute;inset:-1px;border-radius:inherit;background:linear-gradient(90deg,#756cff33,#22d3ee33,transparent);z-index:-1;filter:blur(5px)}`,
    `.x100-search:before{content:"";position:absolute;inset:-110px;background:#000b;opacity:0;transition:.45s;z-index:-1;border-radius:40px}.x100-search:focus-within:before{opacity:1}.x100-search-row:focus-within{background:#1a1d25;border-color:#fff4;box-shadow:0 0 0 1px #fff2,0 0 45px #ffffff18}.x100-search:focus-within .x100-results{opacity:.35}`,
    `.x100-results{transform:rotateX(28deg) translateY(-12px) translateZ(-65px);transform-origin:top;opacity:.65;box-shadow:0 30px 50px #0009}.x100-search:focus-within .x100-results{transform:rotateX(12deg) translateY(0) translateZ(-25px);opacity:1}.x100-results span:nth-child(2){transform:translateZ(-18px)}.x100-results span:nth-child(3){transform:translateZ(-35px)}`,
    `.x100-search-particle{position:absolute;width:5px;height:5px;border-radius:50%;background:hsl(var(--h) 90% 70%);left:50%;top:24px;z-index:9;animation:x100-search-pop .65s ease-out forwards}@keyframes x100-search-pop{to{transform:translate(var(--x),var(--y)) scale(.1);opacity:0}}`,
    `.x100-search-row{padding-right:47px}.x100-ai-orb{display:block;position:absolute;right:10px;width:27px;height:27px;border-radius:50%;background:radial-gradient(circle at 35% 30%,#fff,#a78bfa 18%,#4338ca 58%,#111827 72%);box-shadow:0 0 calc(8px + var(--energy,0)*1px) #756cff;transform:scale(calc(1 + var(--energy,0)*.006));transition:.25s}.x100-ai-orb:after{content:"";position:absolute;inset:-5px;border:1px solid #756cff55;border-radius:50%;animation:x100-ai-orbit 3s linear infinite}@keyframes x100-ai-orbit{to{rotate:360deg}}`,
    `.x100-search-row{padding-right:78px}.x100-wave{display:flex;position:absolute;right:10px;height:25px;align-items:center;gap:3px}.x100-wave b{display:block;width:3px;height:8px;border-radius:5px;background:#22d3ee;animation:x100-voice 1s ease-in-out infinite}.x100-wave b:nth-child(2){animation-delay:.12s}.x100-wave b:nth-child(3){animation-delay:.24s}.x100-wave b:nth-child(4){animation-delay:.36s}@keyframes x100-voice{50%{height:24px;background:#756cff}}`,
    `.x100-results{transform-style:preserve-3d;perspective:250px;overflow:hidden;background:radial-gradient(ellipse at top,#756cff22,#0d0f15 55%)}.x100-results span{transform:translateZ(var(--z)) scale(var(--s));animation:x100-tunnel 3s ease-in-out infinite}.x100-results span:nth-child(1){--z:0px;--s:1}.x100-results span:nth-child(2){--z:-45px;--s:.92;animation-delay:.4s}.x100-results span:nth-child(3){--z:-90px;--s:.84;animation-delay:.8s}@keyframes x100-tunnel{50%{transform:translateY(5px) translateZ(12px) scale(1.03)}}`,
    `.x100-magnifier{display:grid;place-items:center;position:absolute;width:38px;height:38px;border:2px solid #fff8;border-radius:50%;top:58px;left:4px;font-style:normal;color:#fff;background:#ffffff08;backdrop-filter:blur(3px);box-shadow:0 8px 18px #0006;animation:x100-magnify 3s ease-in-out infinite}.x100-magnifier:after{content:"";position:absolute;width:16px;height:2px;background:#fff8;right:-11px;bottom:-5px;rotate:45deg;border-radius:2px}@keyframes x100-magnify{50%{left:225px;top:100px;transform:scale(1.16)}}`,
    `.x100-search{padding:10px;border:1px solid #ffffff16;border-radius:20px;background:#ffffff08;backdrop-filter:blur(24px) saturate(160%);box-shadow:0 26px 55px #0007,inset 0 1px #fff2}.x100-search-row{background:#ffffff08}.x100-results{background:#ffffff04}.x100-results span{background:#ffffff08}`,
    `.x100-search{height:195px}.x100-results{position:absolute;inset:62px 0 0;border-radius:50%;background:radial-gradient(circle,#756cff20,transparent 65%);border:0}.x100-results span{position:absolute;width:52px;height:52px;padding:0;border-radius:50%;display:grid;place-items:center;text-align:center;background:radial-gradient(circle at 35% 25%,#fff6,#756cff 16%,#252059 70%);font-size:7px;color:#fff;box-shadow:0 0 16px #756cff44;animation:x100-galaxy 7s linear infinite}.x100-results span:nth-child(1){left:15px;top:45px}.x100-results span:nth-child(2){right:18px;top:18px;animation-direction:reverse}.x100-results span:nth-child(3){left:112px;top:65px;animation-duration:5s}@keyframes x100-galaxy{to{rotate:360deg}}`,
  ]
  let js: string | undefined
  if (index === 3) js = `const s=document.querySelector('.x100-search'),i=s.querySelector('input'),b=s.querySelector('button');b.addEventListener('click',()=>{i.value='';for(let n=0;n<14;n++){const p=document.createElement('i'),a=Math.PI*2*n/14,d=30+Math.random()*50;p.className='x100-search-particle';p.style.setProperty('--x',Math.cos(a)*d+'px');p.style.setProperty('--y',Math.sin(a)*d+'px');p.style.setProperty('--h',String(n*26));s.appendChild(p);setTimeout(()=>p.remove(),700)}})`
  if (index === 4) js = `const i=document.querySelector('.x100-search input'),o=document.querySelector('.x100-ai-orb');const u=()=>o.style.setProperty('--energy',String(Math.min(10,i.value.length)));i.addEventListener('input',u);u()`
  return { html, css: base + variants[index], js }
}

