function buildFeedback(index: number, idea: Idea): Built {
  const labels = ['SUCCESS','SAVED','ERROR','FAILED','WARNING','ACHIEVED','DELETE','ARCHIVE','UNDO','SAVE']
  const html = `<div class="x100-feedback"><div class="x100-feedback-icon">${['✓','✓','!','!','⚠','★','×','↓','↶','✓'][index]}</div><strong>${labels[index]}</strong><span>${esc(idea[0])}</span><button type="button">Trigger</button><i class="x100-fx"></i></div>`
  const base = `.x100-feedback{position:relative;width:235px;padding:20px;border:1px solid #ffffff14;border-radius:18px;background:#11141b;color:#fff;text-align:center;overflow:hidden;box-shadow:0 20px 38px #0006}.x100-feedback-icon{width:46px;height:46px;margin:0 auto 10px;border-radius:50%;display:grid;place-items:center;background:#756cff22;border:1px solid #756cff55;color:#a9a4ff;font:900 21px Inter,sans-serif}.x100-feedback strong{display:block;font:900 14px Inter,sans-serif;letter-spacing:.08em}.x100-feedback>span{display:block;margin:5px 0 14px;color:#747d8d;font:500 9px Inter,sans-serif}.x100-feedback button{border:1px solid #ffffff12;border-radius:10px;background:#ffffff07;color:#aab1bd;padding:8px 12px;font:700 9px Inter,sans-serif;cursor:pointer}.x100-fx{position:absolute;pointer-events:none}`
  const variants = [
    `.x100-feedback.play .x100-confetti{position:absolute;left:50%;top:40%;width:7px;height:10px;background:hsl(var(--h) 90% 65%);animation:x100-confetti-fall 1.2s cubic-bezier(.2,.7,.4,1) forwards}@keyframes x100-confetti-fall{0%{transform:translate(0,0) rotate(0)}40%{transform:translate(var(--x),-55px) rotate(180deg)}100%{transform:translate(calc(var(--x)*1.2),95px) rotate(520deg);opacity:0}}`,
    `.x100-feedback-icon{background:#2dd4bf22;border-color:#2dd4bf66;color:#5eead4}.x100-feedback.play .x100-feedback-icon:after{content:"";position:absolute;width:46px;height:46px;border:2px solid #2dd4bf;border-radius:50%;animation:x100-shock .85s ease-out forwards}@keyframes x100-shock{to{transform:scale(4.5);opacity:0}}`,
    `.x100-feedback-icon{background:#fb718522;border-color:#fb718566;color:#fb7185}.x100-feedback.play{animation:x100-error-physics .75s cubic-bezier(.3,.9,.4,1)}@keyframes x100-error-physics{0%,100%{transform:translateX(0) rotate(0)}15%{transform:translateX(-16px) rotate(-3deg)}30%{transform:translateX(13px) rotate(2.5deg)}48%{transform:translateX(-9px) rotate(-1.7deg)}64%{transform:translateX(6px) rotate(1deg)}80%{transform:translateX(-3px) rotate(-.5deg)}}`,
    `.x100-feedback-icon{background:#fb718522;border-color:#fb718566;color:#fb7185}.x100-feedback.play{animation:x100-rgb-error .48s steps(2)}.x100-feedback.play:before,.x100-feedback.play:after{content:"ERROR";position:absolute;left:0;right:0;top:45%;font:900 34px monospace;opacity:.22;pointer-events:none}.x100-feedback.play:before{color:#22d3ee;transform:translateX(-5px)}.x100-feedback.play:after{color:#f43f5e;transform:translateX(5px)}@keyframes x100-rgb-error{20%{transform:translateX(4px) skewX(3deg)}40%{transform:translateX(-6px)}60%{filter:hue-rotate(90deg)}80%{transform:translateX(2px)}}`,
    `.x100-feedback-icon{background:#fbbf2422;border-color:#fbbf2466;color:#fbbf24}.x100-feedback.play{animation:x100-warning-pulse 1.2s ease-in-out 2}@keyframes x100-warning-pulse{50%{box-shadow:0 0 0 1px #fbbf2444,0 0 42px #fbbf2433,inset 0 0 25px #fbbf2410;transform:scale(1.02)}}`,
    `.x100-feedback-icon{color:#fbbf24;border-color:#fbbf2466;background:#fbbf2415}.x100-feedback.play .x100-feedback-icon{animation:x100-achieve .75s cubic-bezier(.2,1.6,.3,1)}.x100-feedback.play:before{content:"✦  ★  ✧  ✦  ★";position:absolute;left:10px;right:10px;top:38px;color:#fbbf24;letter-spacing:12px;animation:x100-stars-explode .9s ease-out forwards}@keyframes x100-achieve{50%{transform:translateY(-18px) scale(1.7) rotate(12deg)}}@keyframes x100-stars-explode{to{transform:translateY(-45px) scale(1.8);opacity:0}}`,
    `.x100-feedback.play{animation:x100-dissolve-card .9s ease-in forwards}.x100-feedback.play:after{content:"";position:absolute;inset:0;background:repeating-radial-gradient(circle,#11141b 0 2px,transparent 3px 7px);animation:x100-dust .9s ease-out forwards}@keyframes x100-dissolve-card{70%{filter:blur(3px);transform:scale(.96)}100%{opacity:.08;transform:scale(.82)}}@keyframes x100-dust{to{transform:translateY(-35px) scale(1.4);opacity:0}}`,
    `.x100-feedback:after{content:"▰";position:absolute;right:15px;bottom:12px;color:#756cff;font-size:26px}.x100-feedback.play{animation:x100-vacuum .9s cubic-bezier(.55,.05,.75,.2) forwards;transform-origin:90% 88%}@keyframes x100-vacuum{55%{transform:translate(55px,28px) scale(.5) rotate(18deg);filter:blur(1px)}100%{transform:translate(100px,45px) scale(.03) rotate(80deg);opacity:0}}`,
    `.x100-feedback.removed{transform:translateX(80px) scale(.35) rotate(12deg);opacity:0;transition:.55s}.x100-feedback.restoring{animation:x100-undo-reverse .7s cubic-bezier(.2,1.2,.2,1)}@keyframes x100-undo-reverse{0%{transform:translateX(80px) scale(.35) rotate(12deg);opacity:0}100%{transform:none;opacity:1}}`,
    `.x100-feedback.play:after{content:"";position:absolute;top:-30%;left:-40%;width:28%;height:160%;background:linear-gradient(90deg,transparent,#fff,transparent);transform:rotate(18deg);filter:blur(1px);animation:x100-save-flash .75s ease-out forwards}.x100-feedback.play .x100-feedback-icon{box-shadow:0 0 28px #2dd4bf66;color:#2dd4bf}@keyframes x100-save-flash{to{left:130%}}`,
  ]
  let js = `const c=document.querySelector('.x100-feedback'),b=c.querySelector('button');const play=()=>{c.classList.remove('play');void c.offsetWidth;c.classList.add('play');setTimeout(()=>c.classList.remove('play'),1600)};b.addEventListener('click',play);`
  if (index === 0) js = `const c=document.querySelector('.x100-feedback'),b=c.querySelector('button');b.addEventListener('click',()=>{c.classList.add('play');for(let i=0;i<22;i++){const p=document.createElement('i');p.className='x100-confetti';p.style.setProperty('--x',(Math.random()*150-75)+'px');p.style.setProperty('--h',String(Math.random()*360));c.appendChild(p);setTimeout(()=>p.remove(),1300)}setTimeout(()=>c.classList.remove('play'),1400)})`
  if (index === 8) js = `const c=document.querySelector('.x100-feedback'),b=c.querySelector('button');let removed=false;b.addEventListener('click',()=>{if(!removed){c.classList.add('removed');b.textContent='Undo';removed=true;setTimeout(()=>{c.style.opacity='';},100)}else{c.classList.remove('removed');c.classList.add('restoring');b.textContent='Trigger';removed=false;setTimeout(()=>c.classList.remove('restoring'),750)}})`
  return { html, css: base + variants[index], js }
}

